from collections import defaultdict, Counter

def group_aggregate(rows, key, value):
    if not rows:
        return {}

    result = defaultdict(lambda: {'count': 0, 'sum': 0.0, 'min': float('inf'), 'max': float('-inf'), 'mean': 0.0})

    for row in rows:
        if key in row and row[key] is not None:
            try:
                val = float(row[value])
                result[row[key]]['count'] += 1
                result[row[key]]['sum'] += val
                result[row[key]]['min'] = min(result[row[key]]['min'], val)
                result[row[key]]['max'] = max(result[row[key]]['max'], val)
                result[row[key]]['mean'] = result[row[key]]['sum'] / result[row[key]]['count']
            except ValueError:
                continue

    return dict(result)

import random

def reservoir_sample(stream, k, seed):
    if k <= 0:
        return []

    rng = random.Random(seed)
    reservoir = []

    for i, item in enumerate(stream):
        if i < k:
            reservoir.append(item)
        else:
            j = rng.randint(0, i)
            if j < k:
                reservoir[j] = item

    return reservoir

