def version_compare(a: str, b: str) -> int:
    def parse_version(version: str) -> List[int]:
        version = version.lstrip('vV').split('.')
        return [int(component) for component in version if component.isdigit()]

    a_parts = parse_version(a)
    b_parts = parse_version(b)

    for i in range(max(len(a_parts), len(b_parts))):
        a_part = a_parts[i] if i < len(a_parts) else 0
        b_part = b_parts[i] if i < len(b_parts) else 0

        if a_part < b_part:
            return -1
        elif a_part > b_part:
            return 1

    return 0

import re

def detect_bruteforce(lines, threshold=5) -> dict[str, int]:
    ip_counts = {}

    for line in lines:
        match = re.search(r'Failed password for \w+ from (\d+\.\d+\.\d+\.\d+) port \d+ ssh2', line)
        if match:
            ip = match.group(1)
            if ip in ip_counts:
                ip_counts[ip] += 1
            else:
                ip_counts[ip] = 1

    return {ip: count for ip, count in ip_counts.items() if count >= threshold}

import re

def extract_iocs(text: str) -> dict:
    def refang(text: str) -> str:
        text = text.replace('[.]', '.')
        text = text.replace('(.)', '.')
        text = text.replace('{.}', '.')
        text = text.replace('hxxp', 'http')
        return text.lower()

    def is_valid_ipv4(ip: str) -> bool:
        parts = ip.split('.')
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit() or not (0 <= int(part) <= 255):
                return False
        return True

    def is_valid_domain(domain: str) -> bool:
        return re.match(r'\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}\b', domain) is not None

    def is_valid_sha256(sha256: str) -> bool:
        return re.match(r'\b[a-f0-9]{64}\b', sha256) is not None

    text = refang(text)

    ipv4 = sorted(set(re.findall(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text)))
    domains = sorted(set(re.findall(r'\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}\b', text)))
    sha256 = sorted(set(re.findall(r'\b[a-f0-9]{64}\b', text)))

    return {"ipv4": ipv4, "domains": domains, "sha256": sha256}

