    def is_encoded_command(cmd: str) -> bool:
        encoded_pattern = re.compile(r'(-e|-en|-enc|-encodedcommand\b)[\s]+[A-Za-z0-9+/=]{20,}')
        return encoded_pattern.search(cmd) is not None

    def is_download_cradle(cmd: str) -> bool:
        download_patterns = [
            r'downloadstring',
            r'downloadfile',
            r'invoke-webrequest',
            r'iwr ',
            r'start-bitstransfer',
            r'curl\b[^|]*\|\s*(ba)?sh\b',
            r'wget\b[^|]*\|\s*(ba)?sh\b'
        ]
        return any(pattern in cmd.lower() for pattern in download_patterns)

    def is_hidden_window(cmd: str) -> bool:
        hidden_pattern = re.compile(r'(-w|-windowstyle\b)[\s]+hidden')
        return hidden_pattern.search(cmd) is not None

    def is_execution_policy_bypass(cmd: str) -> bool:
        bypass_pattern = re.compile(r'(-ep|-exec|-executionpolicy\b)[\s]+bypass')
        return bypass_pattern.search(cmd) is not None

    def is_lolbin(cmd: str) -> bool:
        lolbin_patterns = [
            r'certutil\b.*-urlcache',
            r'mshta\b.*http(s)?',
            r'regsvr32\b.*\/i:http(s)?',
            r'rundll32\b.*javascript:'
        ]
        return any(pattern in cmd.lower() for pattern in lolbin_patterns)

    iocs = set()
    if is_encoded_command(cmd):
        iocs.add("encoded_command")
    if is_download_cradle(cmd):
        iocs.add("download_cradle")
    if is_hidden_window(cmd):
        iocs.add("hidden_window")
    if is_execution_policy_bypass(cmd):
        iocs.add("execution_policy_bypass")
    if is_lolbin(cmd):
        iocs.add("lolbin")

    return sorted(iocs)
